-- Dragging (mouse + touch) via the title bar.
local dragging = false
local dragStart, startPos

titleBar.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = main.Position
        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                dragging = false
            end
        end)
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dragging
        and (input.UserInputType == Enum.UserInputType.MouseMovement
            or input.UserInputType == Enum.UserInputType.Touch) then
        local delta = input.Position - dragStart
        main.Position = UDim2.new(
            startPos.X.Scale, startPos.X.Offset + delta.X,
            startPos.Y.Scale, startPos.Y.Offset + delta.Y
        )
    end
end)

-- Toggle + 15s execution loop.
local enabled = false
local loopToken = 0

local function setVisualState(on)
    if on then
        toggle.Text = "Stop Dupe"
        toggle.BackgroundColor3 = Color3.fromRGB(196, 64, 64)
        status.Text = "Status: ON (every " .. RUN_INTERVAL .. "s)"
    else
        toggle.Text = "Start Dupe"
        toggle.BackgroundColor3 = Color3.fromRGB(60, 60, 70)
        status.Text = "Status: OFF"
    end
end

local function safeRun()
    local ok, err = pcall(runDupe)
    if not ok then
        warn("[DUPE] execution error: " .. tostring(err))
        status.Text = "Status: ON (last run errored)"
    end
end

local function startLoop()
    loopToken = loopToken + 1
    local myToken = loopToken
    task.spawn(function()
        while enabled and myToken == loopToken do
            safeRun()
            -- Interruptible wait so toggling OFF stops promptly.
            local waited = 0
            while enabled and myToken == loopToken and waited < RUN_INTERVAL do
                task.wait(1)
                waited = waited + 1
            end
        end
    end)
end

toggle.MouseButton1Click:Connect(function()
    enabled = not enabled
    setVisualState(enabled)
    if enabled then
        startLoop()
    else
        loopToken = loopToken + 1 -- invalidate any running loop
    end
end)

print("[DUPE] menu loaded. Toggle the button to run every " .. RUN_INTERVAL .. "s.")
